from itertools import cycle, islice
from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import method_decorator
from taf.rfrl.csv4all.resources.test_cases.module_test import ModuleTest
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class ModuleLockUnlockTest(ModuleTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, module_type: str, calculate_kpi: Optional[bool] = True,
                 kpi_targets: Optional[dict] = None, use_dcap: Optional[bool] = False,
                 qc_domain: Optional[str] = None, qc_id: Optional[str] = None, qc_project: Optional[str] = None,
                 customers_list: Optional[list] = None, report_comment: Optional[str] = None,
                 sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, calculate_kpi, kpi_targets,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment,
                         sw_build, topology, stop_test_after_fail, l3_call_method, detailed_console_log,
                         collect_passed_logs)
        self.module_type = module_type

    def test_operation(self, node):
        locked_module = next(node.modules_for_test)
        node.btsverify.locked_objects.append(locked_module)
        slave_nodes = self.add_1931_if_radio_module_lock(node, locked_module)
        node.btsverify.set_locked_object()
        node.lock_entity(node.btsverify.locked_objects)
        self.failed_nodes[node.node_alias].update(self.run_verification(hw_timer=90, alarm_timer=30))
        self.multi_runner.start_watching_alarms_on_all_nodes()
        self.multi_runner.start_log_tracing_all_nodes()
        node.unlock_entity(node.btsverify.locked_objects)
        self.clear_locked_objects_list()
        self.remove_1931_alarm_from_allowed(slave_nodes)

    def clear_locked_objects_list(self):
        for node in self.nodes:
            node.btsverify.clear_locked_objects_list()

    @method_decorator()
    def add_1931_if_radio_module_lock(self, node, rmod):
        affected_nodes = []
        if self.module_type == "radio":
            for slave_node in self.nodes:
                if slave_node is not node:
                    for slave_rmod, rmod_details in slave_node.radioModules.items():
                        if rmod_details.get("Serial Number") == node.radioModules[rmod].get("Serial Number"):
                            slave_node.btsverify.rmod_verifier.locked_modules.append(slave_rmod)
                            rmod_mapped_cells = slave_node.radioModules[slave_rmod].get("Mapped Cells")
                            slave_node.btsverify.cells_verifier.affected_cells = [cell for cell in rmod_mapped_cells]
                            affected_nodes.append(slave_node)
            self.add_allowed_fault_alarm_for_slave(node, "1931", node.radioModules[rmod].get("Serial Number"))
        return affected_nodes

    @staticmethod
    def remove_1931_alarm_from_allowed(affected_nodes):
        if affected_nodes:
            for node in affected_nodes:
                for alarm in node.test_specific_alarms:
                    if alarm.fault_id == "1931" and "1931" in node.test_specific_alarms:
                        node.test_specific_alarms.remove(alarm)

    def clear_dependent_radios(self):
        for node in self.nodes:
            node.dependent_radios = []

    @method_decorator()
    def set_l3_all_dependent_cells(self, node):
        self.l3_call_dependent_cells = [cell for rat_cells in node.cells_per_rat.values() for cell in rat_cells]

    @method_decorator()
    def set_modules_eligible_for_test(self):
        test_logger("Setting modules eligible for test")
        nodes_without_eligible_modules = []
        for node in self.test_nodes:
            modules = {}
            if self.module_type == "radio":
                modules = node.radioModules
            elif self.module_type == "baseband":
                modules = node.basebandModules
            if self.module_type == "baseband":
                modules_for_test = [module for module, module_inf in modules.items()]
            else:
                modules_for_test = [module for module, module_inf in modules.items()
                                    if module_inf.get("Eligible For Reset") is True]
            if hasattr(node, "modules_for_test"):
                test_logger(f"Modules for test provided by user: {node.modules_for_test}")
                modules_for_test = [module for module in modules_for_test if module in node.modules_for_test]
            test_logger(f"Eligible modules for node {node.node_alias} {modules_for_test}")
            node.modules_for_test = iter(islice(cycle(modules_for_test), 2*self.iterations_per_node))
            if not modules_for_test:
                test_logger(f"Node {node.node_alias} doesn't have any {self.module_type} modules,"
                            f" which are eligible for test. This node will be removed from test scope",
                            log_level="WARN")
                nodes_without_eligible_modules.append(node)

        for node in nodes_without_eligible_modules:
            self.test_nodes.remove(node)
        if not self.test_nodes:
            raise Exception("There is no Node with eligible modules for test!!!")
